def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    marker = next((r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == 2)

    # Find the repeated horizontal 8-lines.
    walls = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= w // 2]
    holes = {r: [c for c, v in enumerate(grid[r]) if v == 0] for r in walls}

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 2

    if not walls:
        return out

    first = walls[0]
    # Connect the starting marker to the openings in the first line.
    endpoints = holes[first] + [marker[1]]
    for c in range(min(endpoints), max(endpoints) + 1):
        paint(first - 1, c)
    for c in holes[first]:
        paint(first, c)

    # Connect openings from one 8-line to the next.
    for upper, lower in zip(walls, walls[1:]):
        top_holes, bottom_holes = holes[upper], holes[lower]
        gap = lower - upper - 1

        if gap == 1:
            endpoints = top_holes + bottom_holes
            for c in range(min(endpoints), max(endpoints) + 1):
                paint(upper + 1, c)
        elif gap >= 2:
            for c in top_holes:
                paint(upper + 1, c)
            for c in range(w):
                paint(upper + 2, c)
            for r in range(upper + 3, lower):
                for c in top_holes:
                    paint(r, c)

        for c in bottom_holes:
            paint(lower, c)

    # Continue the final openings down to the edge.
    for c in holes[walls[-1]]:
        for r in range(walls[-1] + 1, h):
            paint(r, c)

    return out
